INSERT INTO rubric_criteria (goal_number, phase, phase_description, sort_order, criterion_text, description_insufficient, description_sufficient, description_good) VALUES
(1, 1, 'Je voert zelfstandig een project uit dat past binnen je comfortzone. Je regelt je eigen project, maakt een planning (met hulp) en kijkt terug op het project en je rol daarin.', 0, 'Zelfstandig en binnen je comfortzone een project opzetten', 'De student zet geen project op of heeft hierbij voortdurend sturing nodig.', 'De student zet een project op, maar heeft daarbij regelmatig sturing nodig.', 'De student zet zelfstandig een project op binnen de eigen comfortzone, zonder dat daar sturing voor nodig is.'),
(1, 1, 'Je voert zelfstandig een project uit dat past binnen je comfortzone. Je regelt je eigen project, maakt een planning (met hulp) en kijkt terug op het project en je rol daarin.', 1, 'Het project uitvoeren en daarin regie nemen', 'De student voert het project niet uit of neemt geen regie over de uitvoering.', 'De student voert het project grotendeels uit en neemt regie, maar laat zich soms leiden door anderen.', 'De student voert het project zelfstandig uit en neemt duidelijk de regie, ook als iets anders loopt dan verwacht.'),
(1, 1, 'Je voert zelfstandig een project uit dat past binnen je comfortzone. Je regelt je eigen project, maakt een planning (met hulp) en kijkt terug op het project en je rol daarin.', 2, 'Plannen (week en dag, met ondersteuning)', 'De student maakt geen of een onbruikbare planning, ook niet met ondersteuning.', 'De student maakt een planning met ondersteuning, maar deze is niet altijd volledig of realistisch.', 'De student maakt een volledige en realistische week- en dagplanning met ondersteuning die duidelijk leidt naar het beoogde resultaat.'),
(1, 1, 'Je voert zelfstandig een project uit dat past binnen je comfortzone. Je regelt je eigen project, maakt een planning (met hulp) en kijkt terug op het project en je rol daarin.', 3, 'Reflecteren op het proces en het resultaat', 'De student reflecteert niet of beschrijft alleen wat er is gebeurd zonder lering te trekken.', 'De student reflecteert op het proces en het resultaat, maar blijft oppervlakkig en trekt geen duidelijke conclusies.', 'De student reflecteert diepgaand op het proces en het resultaat, zowel tijdens als na het project, en benoemt wat hij of zij hiervan heeft geleerd.'),
(1, 1, 'Je voert zelfstandig een project uit dat past binnen je comfortzone. Je regelt je eigen project, maakt een planning (met hulp) en kijkt terug op het project en je rol daarin.', 4, 'Authenticiteit en actualiteit', 'Het ingeleverde werk is niet aantoonbaar van de student zelf of is niet recent.', 'Het ingeleverde werk is grotendeels aantoonbaar van de student zelf en recent, maar niet altijd even duidelijk.', 'Het ingeleverde werk is aantoonbaar van de student zelf, recent en laat duidelijk zien wat de student heeft gedaan en geleerd.'),
(1, 2, 'Je durft meer buiten je comfortzone te werken. Je bedenkt en voert zelfstandig projecten uit, maakt zelf een planning en neemt verantwoordelijkheid. Je vraagt actief feedback en gebruikt dit om je werk te verbeteren.', 0, 'Zelfstandig en (deels) buiten je comfortzone projecten bedenken en uitvoeren', 'De student bedenkt geen eigen projecten of blijft volledig binnen de comfortzone.', 'De student bedenkt en voert grotendeels zelfstandig projecten uit, maar blijft deels binnen de comfortzone of heeft af en toe sturing nodig.', 'De student bedenkt en voert volledig zelfstandig projecten uit die aantoonbaar deels buiten de comfortzone liggen.'),
(1, 2, 'Je durft meer buiten je comfortzone te werken. Je bedenkt en voert zelfstandig projecten uit, maakt zelf een planning en neemt verantwoordelijkheid. Je vraagt actief feedback en gebruikt dit om je werk te verbeteren.', 1, 'Projecten zelfstandig plannen', 'De student maakt geen of een onbruikbare planning.', 'De student maakt zelfstandig een planning, maar deze is niet altijd volledig of realistisch genoeg om het doel te bereiken.', 'De student maakt zelfstandig een volledige en realistische planning die duidelijk leidt naar het beoogde resultaat.'),
(1, 2, 'Je durft meer buiten je comfortzone te werken. Je bedenkt en voert zelfstandig projecten uit, maakt zelf een planning en neemt verantwoordelijkheid. Je vraagt actief feedback en gebruikt dit om je werk te verbeteren.', 2, 'Een project bijsturen als dat tijdens de uitvoering nodig is', 'De student stuurt niet bij als het project anders loopt dan gepland.', 'De student stuurt bij als het project anders loopt, maar doet dit niet altijd tijdig of gericht genoeg.', 'De student herkent tijdig wanneer bijsturing nodig is en stuurt aantoonbaar en gericht bij tijdens de uitvoering.'),
(1, 2, 'Je durft meer buiten je comfortzone te werken. Je bedenkt en voert zelfstandig projecten uit, maakt zelf een planning en neemt verantwoordelijkheid. Je vraagt actief feedback en gebruikt dit om je werk te verbeteren.', 3, 'Verantwoordelijkheid nemen voor de uitvoering', 'De student neemt onvoldoende verantwoordelijkheid, haalt deadlines niet of stelt te weinig vragen.', 'De student neemt verantwoordelijkheid, maar haalt niet altijd deadlines of stelt niet altijd vragen als dat nodig is.', 'De student neemt volledig verantwoordelijkheid voor de uitvoering, haalt deadlines consequent en stelt proactief vragen als dat nodig is.'),
(1, 2, 'Je durft meer buiten je comfortzone te werken. Je bedenkt en voert zelfstandig projecten uit, maakt zelf een planning en neemt verantwoordelijkheid. Je vraagt actief feedback en gebruikt dit om je werk te verbeteren.', 4, 'Feedback vragen op (delen van) het project', 'De student vraagt zelden of nooit om feedback.', 'De student vraagt om feedback, maar doet dit niet altijd actief, specifiek of gericht op concrete onderdelen.', 'De student vraagt actief en specifiek om feedback op concrete onderdelen van het project.'),
(1, 2, 'Je durft meer buiten je comfortzone te werken. Je bedenkt en voert zelfstandig projecten uit, maakt zelf een planning en neemt verantwoordelijkheid. Je vraagt actief feedback en gebruikt dit om je werk te verbeteren.', 5, 'Feedback verwerken in het project', 'De student verwerkt feedback niet of nauwelijks in het eigen werk.', 'De student verwerkt feedback in het werk, maar legt niet altijd uit waarom bepaalde feedback wel of niet is gebruikt.', 'De student verwerkt feedback aantoonbaar in het werk en legt altijd duidelijk uit waarom bepaalde feedback wel of niet is gebruikt.'),
(1, 2, 'Je durft meer buiten je comfortzone te werken. Je bedenkt en voert zelfstandig projecten uit, maakt zelf een planning en neemt verantwoordelijkheid. Je vraagt actief feedback en gebruikt dit om je werk te verbeteren.', 6, 'Reflecteren op het proces en op de eigen prestaties', 'De student reflecteert niet of trekt geen conclusies voor een volgend project.', 'De student reflecteert op het proces en de eigen prestaties, maar verbindt dit niet altijd aan concrete leerpunten voor een volgend project.', 'De student reflecteert diepgaand op het proces en de eigen prestaties en formuleert concrete leerpunten die hij of zij wil toepassen in een volgend project.'),
(1, 2, 'Je durft meer buiten je comfortzone te werken. Je bedenkt en voert zelfstandig projecten uit, maakt zelf een planning en neemt verantwoordelijkheid. Je vraagt actief feedback en gebruikt dit om je werk te verbeteren.', 7, 'Authenticiteit en actualiteit', 'Het ingeleverde werk is niet aantoonbaar van de student zelf of is niet recent.', 'Het ingeleverde werk is grotendeels aantoonbaar van de student zelf en recent, maar niet altijd even duidelijk.', 'Het ingeleverde werk is aantoonbaar van de student zelf, recent en laat duidelijk zien wat de student heeft gedaan en geleerd.'),
(1, 3, 'Je werkt samen met klasgenoten aan een project dat meer buiten je comfortzone ligt. Je neemt een duidelijke rol of taak op je en neemt daarvoor verantwoordelijkheid. Je geeft en krijgt feedback en je plant je taken zelfstandig.', 0, 'Samen met klasgenoten een project opzetten en uitvoeren buiten de comfortzone', 'De student werkt niet of nauwelijks samen met klasgenoten of blijft binnen de comfortzone.', 'De student werkt samen met klasgenoten aan een project buiten de comfortzone, maar de eigen bijdrage aan zowel het opzetten als uitvoeren is niet altijd even duidelijk zichtbaar.', 'De student werkt effectief samen met klasgenoten aan een project dat meer buiten de comfortzone ligt dan fase 2, en draagt aantoonbaar bij aan zowel het opzetten als het uitvoeren.'),
(1, 3, 'Je werkt samen met klasgenoten aan een project dat meer buiten je comfortzone ligt. Je neemt een duidelijke rol of taak op je en neemt daarvoor verantwoordelijkheid. Je geeft en krijgt feedback en je plant je taken zelfstandig.', 1, 'Verantwoordelijkheden en rollen binnen de groep goed inzetten', 'De student neemt geen duidelijke rol op zich of pakt de bijbehorende verantwoordelijkheid niet op.', 'De student neemt een rol op zich en pakt de bijbehorende verantwoordelijkheden grotendeels op, maar de eigen bijdrage aan het groepsresultaat is niet altijd even zichtbaar.', 'De student neemt een duidelijke rol op zich, zet de bijbehorende verantwoordelijkheden aantoonbaar goed in en draagt daarmee zichtbaar bij aan het groepsresultaat.'),
(1, 3, 'Je werkt samen met klasgenoten aan een project dat meer buiten je comfortzone ligt. Je neemt een duidelijke rol of taak op je en neemt daarvoor verantwoordelijkheid. Je geeft en krijgt feedback en je plant je taken zelfstandig.', 2, 'Reflecteren op het eigen handelen', 'De student reflecteert niet of nauwelijks op het eigen handelen.', 'De student reflecteert op het eigen handelen, maar verbindt dit niet altijd aan concrete leerpunten voor de toekomst.', 'De student reflecteert diepgaand op het eigen handelen, trekt concrete leerpunten en beschrijft hoe hij of zij dit wil toepassen in toekomstige samenwerkingen.'),
(1, 3, 'Je werkt samen met klasgenoten aan een project dat meer buiten je comfortzone ligt. Je neemt een duidelijke rol of taak op je en neemt daarvoor verantwoordelijkheid. Je geeft en krijgt feedback en je plant je taken zelfstandig.', 3, 'Reflecteren op het handelen van anderen', 'De student reflecteert niet of nauwelijks op het handelen van anderen.', 'De student reflecteert op het handelen van anderen, maar blijft oppervlakkig en trekt geen concrete conclusies.', 'De student reflecteert diepgaand op het handelen van anderen en trekt concrete conclusies over hoe dit de samenwerking heeft beïnvloed.'),
(1, 3, 'Je werkt samen met klasgenoten aan een project dat meer buiten je comfortzone ligt. Je neemt een duidelijke rol of taak op je en neemt daarvoor verantwoordelijkheid. Je geeft en krijgt feedback en je plant je taken zelfstandig.', 4, 'Reflecteren op de samenwerking en het proces', 'De student reflecteert niet of nauwelijks op de samenwerking en het proces.', 'De student reflecteert op de samenwerking en het proces, maar blijft oppervlakkig en benoemt geen concrete verbeterpunten.', 'De student reflecteert diepgaand op de samenwerking en het proces, benoemt concrete verbeterpunten en beschrijft hoe dit de samenwerking kan versterken.'),
(1, 3, 'Je werkt samen met klasgenoten aan een project dat meer buiten je comfortzone ligt. Je neemt een duidelijke rol of taak op je en neemt daarvoor verantwoordelijkheid. Je geeft en krijgt feedback en je plant je taken zelfstandig.', 5, 'Feedback geven en ontvangen', 'De student geeft of ontvangt geen of nauwelijks bruikbare feedback.', 'De student geeft en ontvangt feedback, maar de feedback is niet altijd specifiek of constructief genoeg om van te leren.', 'De student geeft en ontvangt specifieke en constructieve feedback, verwerkt ontvangen feedback aantoonbaar en legt uit waarom bepaalde feedback wel of niet is gebruikt.'),
(1, 3, 'Je werkt samen met klasgenoten aan een project dat meer buiten je comfortzone ligt. Je neemt een duidelijke rol of taak op je en neemt daarvoor verantwoordelijkheid. Je geeft en krijgt feedback en je plant je taken zelfstandig.', 6, 'Werkzaamheden zelfstandig plannen en tussentijds bijsturen', 'De student plant taken niet zelfstandig of stuurt niet bij als dat nodig is.', 'De student plant taken zelfstandig, maar stuurt niet altijd tijdig bij als iets anders loopt dan gepland of stemt dit niet af met de groep.', 'De student plant taken zelfstandig, stuurt tijdig bij als iets anders loopt dan gepland en stemt dit aantoonbaar af met de groep. De planning is realistisch en draagt bij aan het behalen van het groepsdoel.'),
(1, 3, 'Je werkt samen met klasgenoten aan een project dat meer buiten je comfortzone ligt. Je neemt een duidelijke rol of taak op je en neemt daarvoor verantwoordelijkheid. Je geeft en krijgt feedback en je plant je taken zelfstandig.', 7, 'Authenticiteit en actualiteit', 'Het ingeleverde werk is niet aantoonbaar van de student zelf of is niet recent.', 'Het ingeleverde werk is grotendeels aantoonbaar van de student zelf en recent, maar niet altijd even duidelijk.', 'Het ingeleverde werk is aantoonbaar van de student zelf, recent en laat duidelijk zien wat de student heeft gedaan en geleerd.'),
(1, 4, 'Je werkt samen met mensen van buiten school aan een project dat grotendeels buiten je comfortzone ligt. Je neemt je rol en taken serieus en zet je kwaliteiten goed in. Je geeft en krijgt feedback en je plant en stuurt je werk zelfstandig bij.', 0, 'Samen met externen en grotendeels buiten de comfortzone een project opzetten en uitvoeren', 'De student werkt niet of nauwelijks samen met externen of blijft binnen de comfortzone.', 'De student werkt samen met externen aan een project grotendeels buiten de comfortzone, maar past de eigen aanpak niet altijd aan op de context van externen.', 'De student werkt effectief samen met externen aan een project dat grotendeels buiten de comfortzone ligt, past de eigen aanpak aan op de context van externen en draagt aantoonbaar bij aan het resultaat.'),
(1, 4, 'Je werkt samen met mensen van buiten school aan een project dat grotendeels buiten je comfortzone ligt. Je neemt je rol en taken serieus en zet je kwaliteiten goed in. Je geeft en krijgt feedback en je plant en stuurt je werk zelfstandig bij.', 1, 'Verantwoordelijkheden en rollen binnen de groep goed inzetten', 'De student pakt de eigen rol en taken niet op of zet de eigen kwaliteiten niet in.', 'De student pakt de eigen rol en taken op en zet de eigen kwaliteiten in, maar spreekt anderen niet altijd aan als dat nodig is voor het groepsresultaat.', 'De student pakt de eigen rol en taken volledig op, zet de eigen kwaliteiten aantoonbaar goed in en spreekt anderen proactief aan als dat bijdraagt aan het groepsresultaat.'),
(1, 4, 'Je werkt samen met mensen van buiten school aan een project dat grotendeels buiten je comfortzone ligt. Je neemt je rol en taken serieus en zet je kwaliteiten goed in. Je geeft en krijgt feedback en je plant en stuurt je werk zelfstandig bij.', 2, 'Reflecteren op het eigen handelen', 'De student reflecteert niet of nauwelijks op het eigen handelen of vertaalt dit niet naar de toekomst.', 'De student reflecteert op het eigen handelen, maar vertaalt dit niet altijd naar concrete activiteiten in de toekomst of trekt geen lessen uit de samenwerking met externen.', 'De student reflecteert diepgaand op het eigen handelen, vertaalt dit naar concrete activiteiten in de toekomst en betrekt daarbij expliciet de ervaringen met externen als beginnend beroepsbeoefenaar.'),
(1, 4, 'Je werkt samen met mensen van buiten school aan een project dat grotendeels buiten je comfortzone ligt. Je neemt je rol en taken serieus en zet je kwaliteiten goed in. Je geeft en krijgt feedback en je plant en stuurt je werk zelfstandig bij.', 3, 'Reflecteren op het handelen van anderen', 'De student reflecteert niet of nauwelijks op het handelen van anderen.', 'De student reflecteert op het handelen van anderen, maar maakt geen onderscheid tussen hoe klasgenoten en externen handelen.', 'De student reflecteert diepgaand op het handelen van anderen en beschrijft aantoonbaar hoe het samenwerken met externen verschilt van samenwerken met klasgenoten en wat hij of zij daarvan leert.'),
(1, 4, 'Je werkt samen met mensen van buiten school aan een project dat grotendeels buiten je comfortzone ligt. Je neemt je rol en taken serieus en zet je kwaliteiten goed in. Je geeft en krijgt feedback en je plant en stuurt je werk zelfstandig bij.', 4, 'Reflecteren op de samenwerking en het proces', 'De student reflecteert niet of nauwelijks op de samenwerking en het proces.', 'De student reflecteert op de samenwerking en het proces, maar beschrijft niet hoe de samenwerking met externen verschilt van eerdere samenwerkingen.', 'De student reflecteert diepgaand op de samenwerking en het proces, beschrijft expliciet wat de samenwerking met externen anders maakt en trekt lessen voor het eigen functioneren als beginnend beroepsbeoefenaar.'),
(1, 4, 'Je werkt samen met mensen van buiten school aan een project dat grotendeels buiten je comfortzone ligt. Je neemt je rol en taken serieus en zet je kwaliteiten goed in. Je geeft en krijgt feedback en je plant en stuurt je werk zelfstandig bij.', 5, 'Feedback geven en ontvangen', 'De student geeft of ontvangt geen of nauwelijks bruikbare feedback.', 'De student geeft en ontvangt feedback, maar vraagt niet altijd specifieke feedback of verwerkt ontvangen feedback niet consequent.', 'De student vraagt specifieke feedback aan coaches, groepsgenoten én externen, verwerkt deze aantoonbaar en legt uit waarom bepaalde feedback wel of niet is gebruikt.'),
(1, 4, 'Je werkt samen met mensen van buiten school aan een project dat grotendeels buiten je comfortzone ligt. Je neemt je rol en taken serieus en zet je kwaliteiten goed in. Je geeft en krijgt feedback en je plant en stuurt je werk zelfstandig bij.', 6, 'Werk zelfstandig plannen en tussentijds bijsturen', 'De student plant het werk niet zelfstandig of stuurt niet bij als dat nodig is.', 'De student plant het werk zelfstandig en stuurt bij, maar stemt dit niet altijd tijdig af met externen of houdt geen rekening met hun verwachtingen.', 'De student plant het werk zelfstandig, stuurt tijdig bij waar nodig en stemt dit aantoonbaar af met externen. De planning is realistisch en draagt aantoonbaar bij aan het behalen van het projectdoel.'),
(1, 4, 'Je werkt samen met mensen van buiten school aan een project dat grotendeels buiten je comfortzone ligt. Je neemt je rol en taken serieus en zet je kwaliteiten goed in. Je geeft en krijgt feedback en je plant en stuurt je werk zelfstandig bij.', 7, 'Authenticiteit en actualiteit', 'Het ingeleverde werk is niet aantoonbaar van de student zelf of is niet recent.', 'Het ingeleverde werk is grotendeels aantoonbaar van de student zelf en recent, maar niet altijd even duidelijk.', 'Het ingeleverde werk is aantoonbaar van de student zelf, recent en laat duidelijk zien wat de student heeft gedaan en geleerd.'),
(2, 1, 'Je ziet dat je in verschillende werelden leeft. Je kunt uitleggen hoe die werelden en jouw rollen daarin van elkaar verschillen en hoe je daarmee iets kunt toevoegen.', 0, 'Zien dat je in verschillende werelden leeft', 'De student herkent niet dat hij of zij in verschillende werelden leeft.', 'De student herkent dat hij of zij in verschillende werelden leeft, maar beschrijft deze globaal en zonder concrete voorbeelden.', 'De student beschrijft duidelijk en concreet in welke verschillende werelden hij of zij actief is, met voorbeelden uit het eigen leven.'),
(2, 1, 'Je ziet dat je in verschillende werelden leeft. Je kunt uitleggen hoe die werelden en jouw rollen daarin van elkaar verschillen en hoe je daarmee iets kunt toevoegen.', 1, 'Benoemen hoe deze werelden en jouw rollen daarin van elkaar verschillen', 'De student maakt geen onderscheid tussen de eigen werelden en rollen daarin.', 'De student benoemt globaal hoe de werelden en rollen van elkaar verschillen, maar maakt niet altijd onderscheid tussen feiten en aannames over mensen in die werelden.', 'De student benoemt duidelijk hoe de eigen werelden en rollen van elkaar verschillen en maakt daarbij aantoonbaar onderscheid tussen feiten en aannames over mensen in die werelden.'),
(2, 1, 'Je ziet dat je in verschillende werelden leeft. Je kunt uitleggen hoe die werelden en jouw rollen daarin van elkaar verschillen en hoe je daarmee iets kunt toevoegen.', 2, 'Duidelijk maken welke eigenschappen van belang zijn in deze werelden', 'De student benoemt geen of nauwelijks eigen eigenschappen die van belang zijn in de verschillende werelden.', 'De student benoemt eigenschappen, maar legt niet altijd uit waarom deze specifiek van belang zijn in de verschillende werelden.', 'De student maakt duidelijk welke eigenschappen van belang zijn in elk van de verschillende werelden en onderbouwt dit met concrete voorbeelden.'),
(2, 1, 'Je ziet dat je in verschillende werelden leeft. Je kunt uitleggen hoe die werelden en jouw rollen daarin van elkaar verschillen en hoe je daarmee iets kunt toevoegen.', 3, 'Laten zien hoe je vanuit jouw rollen en eigenschappen iets kunt toevoegen', 'De student laat niet zien hoe hij of zij iets kan toevoegen aan de werelden waarin hij of zij actief is.', 'De student laat globaal zien hoe hij of zij iets kan toevoegen, maar de koppeling met de eigen rollen en eigenschappen is niet altijd concreet.', 'De student laat duidelijk en concreet zien hoe hij of zij vanuit de eigen rollen en positieve eigenschappen iets toevoegt aan elk van de werelden waarin hij of zij actief is.'),
(2, 1, 'Je ziet dat je in verschillende werelden leeft. Je kunt uitleggen hoe die werelden en jouw rollen daarin van elkaar verschillen en hoe je daarmee iets kunt toevoegen.', 4, 'Authenticiteit en actualiteit', 'Het ingeleverde werk is niet aantoonbaar van de student zelf of is niet recent.', 'Het ingeleverde werk is grotendeels aantoonbaar van de student zelf en recent, maar niet altijd even duidelijk.', 'Het ingeleverde werk is aantoonbaar van de student zelf, recent en laat duidelijk zien wat de student heeft gedaan en geleerd.'),
(2, 2, 'Je herkent maatschappelijke vraagstukken in je eigen omgeving en bespreekt die met anderen. Je stelt vragen, luistert actief en onderzoekt wat jij belangrijk vindt. Je denkt na over je waarden en overtuigingen en oefent met het kijken vanuit verschillende perspectieven.', 0, 'Maatschappelijke vraagstukken in de eigen omgeving herkennen', 'De student herkent geen maatschappelijke vraagstukken in de eigen omgeving.', 'De student herkent maatschappelijke vraagstukken, maar legt niet altijd uit wat hij of zij daarin persoonlijk belangrijk vindt.', 'De student herkent meerdere maatschappelijke vraagstukken in de eigen omgeving en legt concreet uit wat hij of zij daarin persoonlijk belangrijk vindt.'),
(2, 2, 'Je herkent maatschappelijke vraagstukken in je eigen omgeving en bespreekt die met anderen. Je stelt vragen, luistert actief en onderzoekt wat jij belangrijk vindt. Je denkt na over je waarden en overtuigingen en oefent met het kijken vanuit verschillende perspectieven.', 1, 'Bespreken met medestudenten hoe zij deze ervaren', 'De student bespreekt vraagstukken niet met medestudenten.', 'De student bespreekt vraagstukken met medestudenten, maar vraagt niet altijd actief naar hoe zij deze ervaren.', 'De student bespreekt vraagstukken actief met medestudenten en vraagt gericht naar hoe zij deze ervaren, waarbij de student laat zien dat hij of zij oprecht geïnteresseerd is in andere ervaringen.'),
(2, 2, 'Je herkent maatschappelijke vraagstukken in je eigen omgeving en bespreekt die met anderen. Je stelt vragen, luistert actief en onderzoekt wat jij belangrijk vindt. Je denkt na over je waarden en overtuigingen en oefent met het kijken vanuit verschillende perspectieven.', 2, 'Vragen stellen', 'De student stelt geen of nauwelijks vragen over maatschappelijke vraagstukken.', 'De student stelt vragen, maar deze zijn niet altijd gericht op het beter begrijpen van het vraagstuk of de ander.', 'De student stelt gerichte vragen die aantoonbaar bijdragen aan een beter begrip van het vraagstuk en de ervaringen van anderen.'),
(2, 2, 'Je herkent maatschappelijke vraagstukken in je eigen omgeving en bespreekt die met anderen. Je stelt vragen, luistert actief en onderzoekt wat jij belangrijk vindt. Je denkt na over je waarden en overtuigingen en oefent met het kijken vanuit verschillende perspectieven.', 3, 'Actief luisteren', 'De student luistert niet actief naar anderen tijdens gesprekken over vraagstukken.', 'De student luistert naar anderen, maar reageert niet altijd op wat er gezegd wordt of probeert de ander te overtuigen in plaats van te begrijpen.', 'De student luistert actief, reageert op wat de ander zegt en laat aantoonbaar zien dat hij of zij de ander probeert te begrijpen in plaats van te overtuigen.'),
(2, 2, 'Je herkent maatschappelijke vraagstukken in je eigen omgeving en bespreekt die met anderen. Je stelt vragen, luistert actief en onderzoekt wat jij belangrijk vindt. Je denkt na over je waarden en overtuigingen en oefent met het kijken vanuit verschillende perspectieven.', 4, 'Onderzoeken wat jij in deze maatschappelijke thema''s belangrijk vindt', 'De student onderzoekt niet wat hij of zij persoonlijk belangrijk vindt in maatschappelijke thema''s.', 'De student onderzoekt globaal wat hij of zij belangrijk vindt, maar onderbouwt dit niet altijd met concrete voorbeelden of ervaringen.', 'De student onderzoekt actief wat hij of zij persoonlijk belangrijk vindt in maatschappelijke thema''s en onderbouwt dit aantoonbaar met concrete voorbeelden of ervaringen.'),
