-- Migration: Rubric-based portfolio system
-- Apply via Supabase SQL editor

-- 1. Add phase column to portfolio_items
ALTER TABLE portfolio_items
  ADD COLUMN IF NOT EXISTS phase int NOT NULL DEFAULT 1 CHECK (phase BETWEEN 1 AND 4);

-- Remove old data (user confirmed this is OK)
DELETE FROM portfolio_feedback;
DELETE FROM portfolio_assessments;
DELETE FROM portfolio_items;

-- 2. Create rubric_criteria table
CREATE TABLE IF NOT EXISTS rubric_criteria (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  goal_number int NOT NULL CHECK (goal_number BETWEEN 1 AND 6),
  phase int NOT NULL CHECK (phase BETWEEN 1 AND 4),
  phase_description text NOT NULL DEFAULT '',
  sort_order int NOT NULL DEFAULT 0,
  criterion_text text NOT NULL,
  description_insufficient text NOT NULL DEFAULT '',
  description_sufficient text NOT NULL DEFAULT '',
  description_good text NOT NULL DEFAULT '',
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);

-- 3. Create rubric_scores table
CREATE TABLE IF NOT EXISTS rubric_scores (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  assessment_id uuid NOT NULL REFERENCES portfolio_assessments(id) ON DELETE CASCADE,
  criterion_id uuid NOT NULL REFERENCES rubric_criteria(id),
  score text NOT NULL CHECK (score IN ('onvoldoende', 'voldoende', 'goed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(assessment_id, criterion_id)
);

-- 4. RLS
ALTER TABLE rubric_criteria ENABLE ROW LEVEL SECURITY;
ALTER TABLE rubric_scores ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "rubric_criteria_read_all" ON rubric_criteria;
CREATE POLICY "rubric_criteria_read_all" ON rubric_criteria FOR SELECT USING (true);

DROP POLICY IF EXISTS "rubric_scores_coach_insert" ON rubric_scores;
CREATE POLICY "rubric_scores_coach_insert" ON rubric_scores FOR INSERT
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM portfolio_assessments pa
      WHERE pa.id = assessment_id AND pa.coach_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "rubric_scores_read" ON rubric_scores;
CREATE POLICY "rubric_scores_read" ON rubric_scores FOR SELECT USING (
  EXISTS (
    SELECT 1 FROM portfolio_assessments pa
    JOIN portfolio_items pi ON pi.student_id = pa.student_id
    WHERE pa.id = assessment_id
      AND (pa.coach_id = auth.uid() OR pa.student_id = auth.uid())
  )
);

